import torch


def gen_inputs(ctx, device):
    x_shape = ctx["x__shape"]
    # x = torch.randn(shape).clamp(-0.99, 0.99) to avoid instability near x=-1
    x = torch.randn(x_shape, dtype=torch.float32, device=device).clamp(-0.99, 0.99)
    # n = torch.randint(0, 5, shape) stored as float32 (small positive degrees)
    n = torch.randint(0, 5, x_shape, dtype=torch.float32, device=device)
    return {"x": x, "n": n}


def run_correctness(x, n):
    output = torch.special.chebyshev_polynomial_v(x.float(), n.float())
    return output.to(x.dtype)


def run(x, n):
    return torch.special.chebyshev_polynomial_v(x, n)
